// План specs/addresses.md 1.3 (кейс AD-03). Admin, компания «test». Форму не сохраняем. Зависит от Google Places.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, openNewJobAddressDetails, setEnglish, typeAndPickSuggestion, unitInput } from './address-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Адрес: ручной Unit/Apt сохраняется (#8ffd6e26)', () => {
  test('New Job: manually typed Unit/Apt is kept after picking an address without an apartment #8ffd6e26 @desktop @prod-safe @google-places', async ({ page }) => {
    await setEnglish(page);
    await openNewJobAddressDetails(page);

    await unitInput(page).fill('QA-AUTO 7');
    await typeAndPickSuggestion(page, '1600 Pennsylvania Ave NW Washington', '1600 Pennsylvania Ave NW', 'Washington, DC, USA');

    // Адрес применён (ZIP пришёл) — и только после этого проверяем, что Unit не стёрт.
    await expect(page.getByLabel('ZIP Code', { exact: true })).toHaveValue('20500');
    await expect(page.getByLabel('City', { exact: true })).toHaveValue('Washington');
    await expect(unitInput(page)).toHaveValue('QA-AUTO 7');
  });
});
